declare(strict_types=1); require_once __DIR__.'/server/includes/bootstrap.php'; require_once __DIR__.'/server/includes/view.php'; $user=current_user($pdo); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(limited($pdo, 'contact:'.($_SERVER['REMOTE_ADDR']??'unknown'),6,3600))$error='Too many messages have been submitted from this connection. Try again later.';else{$name=post_string('name',100);$email=strtolower(post_string('email',190));$subject=post_string('subject',160);$message=post_string('message',5000);if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$subject===''||strlen($message)<8)$error='Please complete every field with a valid email and a message of at least 8 characters.';else{$pdo->prepare("INSERT INTO contact_messages(name,email,subject,message,status) VALUES(?,?,?,?,'NEW')")->execute([$name,$email,$subject,$message]);$sent=mail_admin($pdo,$config,'Fortune Apex contact: '.$subject,"A new message was submitted on the website.\n\nName: $name\nEmail: $email\nSubject: $subject\n\n$message\n\nOpen the admin console > Messages to respond.");flash($sent?'success':'warning',$sent?'Message received. The admin team has been notified.':'Message saved to the admin inbox, but email notification was unavailable.');redirect('contact.php');}}}
page_header($config,$user,'Contact us','contact'); ?><section class="hero" style="min-height:240px"><div class="eyebrow">Real people, real inbox</div><h1>LET'S <span>CONNECT.</span></h1><p>Ask about joining, request an account update, report a dispute, or send a question to the Fortune Apex admin team.</p><p class="meta">Support address: <?=e($config['mail']['admin_email']??'Not configured')?></p></section><section class="auth-wrap"><div class="auth-card"><h2>Send us a message</h2><p>The message is saved in the private admin console. Email notifications use the configured SMTP sender.</p><?php if($error): ?><div class="flash error"><?=e($error)?></div><?php endif; ?><form method="post"><?=csrf_field()?><label class="field">Your name<input name="name" maxlength="100" required value="<?=e($user['display_name']??($_POST['name']??''))?>"></label><label class="field">Reply email<input type="email" name="email" maxlength="190" required value="<?=e($user['email']??($_POST['email']??''))?>"></label><label class="field">Subject<select name="subject"><option>Registration / joining</option><option>Account help</option><option>Proposal / system question</option><option>Dispute / report</option><option>Website problem</option><option>Other</option></select></label><label class="field">Message<textarea name="message" maxlength="5000" minlength="8" required placeholder="Tell us what you need help with…"><?=e($_POST['message']??'')?></textarea></label><button class="btn gold" type="submit">Send message</button></form><p class="hint">Forgot your password? Use the <a href="forgot.php">account recovery page</a>.</p></div></section><?php page_footer(); ?>